"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["69120"],{96505(e){e.exports=JSON.parse('{"id":"F243","slug":"event-study-car","name":"Event Study: Abnormal and Cumulative Abnormal Return","subject":"Investments & Portfolio Theory","section":"Market Efficiency","topic":"Event studies","level":"Intermediate","aliases":["abnormal return","CAR","market model event study","announcement effect"],"formula":{"latex":"AR_{t}=R_{t}-(\\\\alpha+\\\\beta R_{m,t}),\\\\quad CAR=\\\\sum AR_{t},\\\\quad t=\\\\frac{CAR}{\\\\sigma_{\\\\varepsilon}\\\\sqrt{N}}","also":[],"text":"Abnormal return = actual return - (alpha + beta x market return); CAR = sum of the abnormal returns; t = CAR / (s x sqrt(N))"},"symbols":[{"symbol":"AR_t","meaning":"Abnormal return on day t, the part not explained by the market","unit":"percent"},{"symbol":"R_t","meaning":"Stock\'s return on day t","unit":"percent"},{"symbol":"alpha, beta","meaning":"Intercept and slope of the stock\'s market model, estimated before the event","unit":"number"},{"symbol":"R_(m,t)","meaning":"Market return on day t","unit":"percent"},{"symbol":"CAR","meaning":"Cumulative abnormal return over the event window","unit":"percent"},{"symbol":"sigma_eps","meaning":"Daily standard deviation of abnormal returns outside the event","unit":"percent"},{"symbol":"N","meaning":"Number of days in the window","unit":"number"}],"when_to_use":"Use it to measure how much a news event, such as an earnings release or a merger announcement, moved a stock beyond what the market did that day. Under efficient markets the effect shows up at once and does not drift afterward.","worked_example":{"problem":"Over a 5-day window around an announcement a stock returned 0.5%, 3.2%, 1.1%, -0.4% and 0.8%, while the market returned 0.2%, 0.5%, 0.3%, -0.2% and 0.1%. Before the event the stock had an alpha of 0.02% a day and a beta of 1.1, and its abnormal returns had a daily standard deviation of 1.2%. Was the reaction significant?","inputs":{"r":[0.5,3.2,1.1,-0.4,0.8],"m":[0.2,0.5,0.3,-0.2,0.1],"alpha":0.02,"beta":1.1,"se":1.2},"steps":[{"label":"Expected return each day = alpha + beta x market return","working":null,"value":"0.0024, 0.0057, 0.0035, -0.0020, 0.0013"},{"label":"Abnormal return each day = actual - expected","working":null,"value":"0.0026, 0.0263, 0.0075, -0.0020, 0.0067"},{"label":"CAR = sum of the abnormal returns","working":null,"value":"4.11%"},{"label":"t = CAR / (se x square root of N)","working":null,"value":"1.53"}],"answer":"The cumulative abnormal return is 4.11%. The t-statistic is 1.53. Beyond about 2 is usually called significant, so this reaction looks real."},"calculator":{"available":true,"inputs":[{"id":"r","label":"Stock returns in the window","unit":"%","type":"list","default":[0.5,3.2,1.1,-0.4,0.8],"hint":""},{"id":"m","label":"Market returns in the window","unit":"%","type":"list","default":[0.2,0.5,0.3,-0.2,0.1],"hint":"Enter in the same order as the stock returns."},{"id":"alpha","label":"Alpha (per day)","unit":"%","type":"number","default":0.02,"hint":""},{"id":"beta","label":"Beta","unit":"","type":"number","default":1.1,"hint":""},{"id":"se","label":"Std dev of abnormal returns (per day)","unit":"%","type":"number","default":1.2,"hint":""}],"checks":[{"expr":"count(r)==count(m) and se>0","message":"Enter the same number of stock and market returns, and a risk above zero."}],"steps":[{"id":"expected","label":"Expected return each day = alpha + beta x market return","expr":"minus(scale(m, beta), -alpha)","format":"list4"},{"id":"ar","label":"Abnormal return each day = actual - expected","expr":"minus(r, expected)","format":"list4"},{"id":"car","label":"CAR = sum of the abnormal returns","expr":"sum(ar)","format":"pct2"},{"id":"t","label":"t = CAR / (se x square root of N)","expr":"car/(se*sqrt(count(r)))","format":"num2"}],"results":["car","t"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"car":4.1100000000000005e-2,"t":1.531706564587356}},"finder":{"finds":"How much an event moved a stock","needs":"Stock and market returns, alpha, beta, residual risk"},"related":[{"slug":"regression-line","name":"Regression Line (Alpha and Beta)"},{"slug":"t-statistic","name":"t-Statistic for a Mean (Hypothesis Test)"},{"slug":"jensens-alpha","name":"Jensen\'s Alpha"}],"related_ids":["F051","F052","F247"],"group":"Markets and instruments","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>A</mi><msub><mi>R</mi><mi>t</mi></msub><mo>=</mo><msub><mi>R</mi><mi>t</mi></msub><mo>\u2212</mo><mo stretchy=\\"false\\">(</mo><mi>\u03B1</mi><mo>+</mo><mi>\u03B2</mi><msub><mi>R</mi><mrow><mi>m</mi><mo separator=\\"true\\">,</mo><mi>t</mi></mrow></msub><mo stretchy=\\"false\\">)</mo><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>C</mi><mi>A</mi><mi>R</mi><mo>=</mo><mo>\u2211</mo><mi>A</mi><msub><mi>R</mi><mi>t</mi></msub><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>t</mi><mo>=</mo><mfrac><mrow><mi>C</mi><mi>A</mi><mi>R</mi></mrow><mrow><msub><mi>\u03C3</mi><mi>\u03B5</mi></msub><msqrt><mi>N</mi></msqrt></mrow></mfrac></mrow><annotation encoding=\\"application/x-tex\\">AR_{t}=R_{t}-(\\\\alpha+\\\\beta R_{m,t}),\\\\quad CAR=\\\\sum AR_{t},\\\\quad t=\\\\frac{CAR}{\\\\sigma_{\\\\varepsilon}\\\\sqrt{N}}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"gas-fee-cost","name":"Ethereum Gas Fee Cost"},"next":{"slug":"ewma-volatility","name":"EWMA Volatility (RiskMetrics)"},"lesson":null,"total":522}')}}]);